INSERT INTO result_fields (id, "order", type, unit, iso2_code, category, comments, source, commodity_metadata, analysis_metadata, created_by) VALUES
    ('Rubber_RBGE_2020', 140, 'numeric', 'ha / %', NULL, 'Commodity datasets', 'Binary layer for South East Asia, 10m, reference year 2020 (imagery 2021 for mainland SEA and 2019 for equatorial Indonesia, designated by the authors as broadly representative of 2020 given long rubber rotations; mature rubber takes ~7 years to reach tapping, so post-2020 planting cannot enter the baseline). Replaces the earlier RBGE map (Wang et al. 2023, previously Rubber_RBGE), which the providers have marked superseded. Deliberately conservative: continental SEA user''s accuracy 0.95, producer''s 0.78, with higher omission in insular SEA.', 'Ahrends, A., Harrison, S. B., Hollingsworth, P. M., Heath, J. D. J., Wang, Y., Xu, J. and Green, J. M. H. (2026). Rubber mapping reveals opportunities and current limitations of deforestation due-diligence. Preprint: https://www.biorxiv.org/content/10.64898/2026.07.25.740673v1 Data: https://zenodo.org/records/21439869', '{"pcrop":{"dataTheme":"commodities","usedForRisk":true},"acrop":{"dataTheme":"commodities","usedForRisk":true},"timber":{"usedForRisk":true}}'::jsonb, '{"type":"float32","excludeFromOutput":false,"isNullable":true,"isRequired":false,"correspondingVariable":"g_rbge_rubber_2020_prep","geeAssets":["ee.Image(\"projects/rubber-499107/assets/rubber_SEA_2020\")"]}'::jsonb, 'migration')
ON CONFLICT (id) DO NOTHING;

